mapper.sql:
/*
     SQL ID : MsgMgrDAO.rcvrSearchCondition
     설  명 : 수신자 검색 조건
 */

    AND U.USER_ID != #{sndngrId}


    AND S.SBJCT_ID = #{sbjctId}


    AND UTA.AUTHRT_CD = #{userTycd}


    AND (U.USERNM LIKE FN_LIKE_VAL(#{searchText})
    OR U.STDNT_NO LIKE FN_LIKE_VAL(#{searchText})
    OR U.USER_ID LIKE FN_LIKE_VAL(#{searchText}))

/*
     SQL ID : MsgMgrDAO.rcvrSearchAllCondition
     설  명 : 수신자 전체 검색 조건
 */

    AND U.USER_ID != #{sndngrId}


    AND EXISTS (
        SELECT 1
        FROM TB_LMS_USER_AUTHRT UAO
        WHERE UAO.USER_ID = U.USER_ID
          AND UAO.ORG_ID = #{orgId}
    )


    AND U.DEPT_ID = #{deptId}


    AND UTA.AUTHRT_CD = #{userTycd}


    AND (U.USERNM LIKE FN_LIKE_VAL(#{searchText})
    OR U.STDNT_NO LIKE FN_LIKE_VAL(#{searchText})
    OR U.USER_ID LIKE FN_LIKE_VAL(#{searchText}))

/*
     SQL ID : MsgMgrDAO.rcvrProfSearchCondition
     설  명 : 교수 수신자 검색 조건
 */

    AND U.USER_ID != #{sndngrId}


    AND U.DEPT_ID = #{deptId}


    AND EXISTS (
        SELECT 1
        FROM TB_LMS_SBJCT_ADM ADM
        WHERE ADM.SBJCT_ID = #{sbjctId}
        AND ADM.USER_ID = U.USER_ID
        AND ADM.SBJCT_ADM_TYCD = 'PROF'
    )


    AND UTA.AUTHRT_CD = #{userTycd}


    AND (U.USERNM LIKE FN_LIKE_VAL(#{searchText})
    OR U.STDNT_NO LIKE FN_LIKE_VAL(#{searchText})
    OR U.USER_ID LIKE FN_LIKE_VAL(#{searchText}))

mapper.select:
/* SQL ID : MsgMgrDAO.selectSmstrList 설 명 : 공통 학기 목록 조회 */ SELECT SC.DGRS_SMSTR_CHRT AS DGRS_SMSTR_CHRT , MAX(SC.SMSTR_CHRTNM) AS SMSTR_CHRTNM FROM TB_LMS_SBJCT S INNER JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID WHERE S.DELYN = 'N'
AND SC.ORG_ID = #{orgId}
AND EXISTS ( SELECT 1 FROM TB_LMS_SBJCT_ADM ADM WHERE ADM.SBJCT_ID = S.SBJCT_ID AND ADM.SBJCT_ADM_TYCD = 'PROF' AND ADM.USER_ID = #{userId} )
AND S.SBJCT_YR = #{sbjctYr}
GROUP BY SC.DGRS_SMSTR_CHRT ORDER BY SC.DGRS_SMSTR_CHRT DESC

/*
SQL ID : MsgMgrDAO.selectSbjctList
설  명 : 공통 운영과목 목록 조회
*/
SELECT DISTINCT S.SBJCT_ID
, S.SBJCTNM
FROM TB_LMS_SBJCT S
INNER JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
WHERE S.DELYN = 'N'

    AND SC.ORG_ID = #{orgId}


    AND EXISTS (
        SELECT 1 FROM TB_LMS_SBJCT_ADM ADM
        WHERE ADM.SBJCT_ID = S.SBJCT_ID
          AND ADM.SBJCT_ADM_TYCD = 'PROF'
          AND ADM.USER_ID = #{userId}
    )


    AND S.SBJCT_YR = #{sbjctYr}


    AND SC.DGRS_SMSTR_CHRT = #{sbjctSmstr}

ORDER BY S.SBJCTNM ASC

/* SQL ID : MsgMgrDAO.selectStdntYrList 설 명 : 학생 수강과목 기준 학사년도 목록 조회 */ SELECT DISTINCT S.SBJCT_YR FROM TB_LMS_ATNDLC A INNER JOIN TB_LMS_SBJCT S ON A.SBJCT_ID = S.SBJCT_ID INNER JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID WHERE S.DELYN = 'N' AND A.USER_ID = #{userId}
AND SC.ORG_ID = #{orgId}
ORDER BY S.SBJCT_YR DESC

/* SQL ID : MsgMgrDAO.selectStdntSmstrList 설 명 : 학생 수강과목 기준 학기 목록 조회 */ SELECT SC.DGRS_SMSTR_CHRT AS DGRS_SMSTR_CHRT , MAX(SC.SMSTR_CHRTNM) AS SMSTR_CHRTNM FROM TB_LMS_ATNDLC A INNER JOIN TB_LMS_SBJCT S ON A.SBJCT_ID = S.SBJCT_ID INNER JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID WHERE S.DELYN = 'N' AND A.USER_ID = #{userId}
AND SC.ORG_ID = #{orgId}
AND S.SBJCT_YR = #{sbjctYr}
GROUP BY SC.DGRS_SMSTR_CHRT ORDER BY SC.DGRS_SMSTR_CHRT DESC

/*
SQL ID : MsgMgrDAO.selectStdntSbjctList
설  명 : 학생 수강과목 기준 운영과목 목록 조회
*/
SELECT DISTINCT S.SBJCT_ID
, S.SBJCTNM
FROM TB_LMS_ATNDLC A
INNER JOIN TB_LMS_SBJCT S ON A.SBJCT_ID = S.SBJCT_ID
INNER JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
WHERE S.DELYN = 'N'
AND A.USER_ID = #{userId}

    AND SC.ORG_ID = #{orgId}


    AND S.SBJCT_YR = #{sbjctYr}


    AND SC.DGRS_SMSTR_CHRT = #{sbjctSmstr}

ORDER BY S.SBJCTNM ASC

/* SQL ID : MsgMgrDAO.selectRcvrByUserIds 설 명 : 엑셀 업로드 수신자 조회 */ SELECT U.USER_ID , U.USERNM , U.STDNT_NO , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = U.USER_ID AND UC.CNTCT_TYCD = 'MBL_PHN') AS MBL_PHN , (SELECT MAX(UC.CNTCT) FROM TB_LMS_USER_CNTCT UC WHERE UC.USER_ID = U.USER_ID AND UC.CNTCT_TYCD = 'INDV_EML') AS EML FROM TB_LMS_USER U WHERE U.USER_ID IN
#{uid}
AND EXISTS (SELECT 1 FROM TB_LMS_USER_AUTHRT UA WHERE UA.USER_ID = U.USER_ID AND UA.ORG_ID = #{orgId})
ORDER BY U.USERNM ASC
